  x.services=rows.services.map(v=>({id:v.id,name:v.name,price:Number(v.price),duration:v.duration,categoryId:v.category_id,staffIds:v.staff_ids||[]}));
  x.customers=rows.customers.map(c=>({id:c.id,name:c.name,email:c.email,phone:c.phone,notes:c.notes}));
  x.bookings=rows.bookings.map(b=>({id:b.id,serviceId:b.service_id,serviceName:b.service_name,price:Number(b.price),duration:b.duration,date:b.date,time:b.time,staffId:b.staff_id,customerId:b.customer_id,name:b.name,email:b.email,phone:b.phone,notes:b.notes,source:b.source,status:b.status,deposit:Number(b.deposit)}));
